package com.inridemart.payment;
import jakarta.validation.constraints.NotNull; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/v1/payments") class PaymentController { final PaymentRepository payments; final OrderClient orders; PaymentController(PaymentRepository p,OrderClient o){payments=p;orders=o;} @PostMapping @Transactional ResponseEntity<Response> process(Authentication a,@RequestHeader("Authorization")String token,@RequestBody Request request){UUID user=(UUID)a.getPrincipal();PaymentEntity payment=payments.findByOrderIdAndUserId(request.orderId(),user).orElseGet(()->payments.save(new PaymentEntity(request.orderId(),user)));if(payment.status!=PaymentStatus.PAID){orders.confirm(payment.orderId,token);payment.status=PaymentStatus.PAID;payments.save(payment);}return ResponseEntity.status(HttpStatus.CREATED).body(Response.of(payment));} @GetMapping("/orders/{orderId}") Response find(Authentication a,@PathVariable UUID orderId){return Response.of(payments.findByOrderIdAndUserId(orderId,(UUID)a.getPrincipal()).orElseThrow());} record Request(@NotNull UUID orderId){} record Response(UUID id,UUID orderId,PaymentStatus status,Instant createdAt){static Response of(PaymentEntity p){return new Response(p.id,p.orderId,p.status,p.createdAt);}} }
